using Nethereum.ABI.FunctionEncoding.Attributes;
using Nethereum.Contracts;

namespace Nethereum.X402.IntegrationTests.Helpers;

[Function("Eip3009BytesSignatureToken", "constructor")]
public class Eip3009BytesSignatureTokenDeployment : ContractDeploymentMessage
{
    public static string BYTECODE =
        "";

    public Eip3009BytesSignatureTokenDeployment() : base(BYTECODE) { }

    [Parameter("string", "_name", 1)]
    public string TokenName { get; set; } = string.Empty;

    [Parameter("string", "_version", 2)]
    public string Version { get; set; } = string.Empty;
}

[Function("Erc1271WrappedSignatureWallet", "constructor")]
public class Erc1271WrappedSignatureWalletDeployment : ContractDeploymentMessage
{
    public static string BYTECODE =
        "";

    public Erc1271WrappedSignatureWalletDeployment() : base(BYTECODE) { }

    [Parameter("address", "_owner", 1)]
    public string Owner { get; set; } = string.Empty;
}
